pointLocator.script:
var etd = [];

for (carril = 1; carril <= 8; carril++) {
    if(typeof this['average_speed_'+ carril] != 'undefined'){
        var det = new Object();

        det.timestamp =this['timestamp_'+ carril].value;
        det.integration_period = this['integration_period_'+ carril].value;
        det.current_direction = this['current_direction_'+ carril].value;
        det.n_vehicles = this['n_vehicules_'+ carril].value;
        det.occupancy = Math.round(this['occupancy_percent_'+ carril].value);
        det.congestion = this['congestion_'+ carril].value;
        det.kamikaze = this['wrongway_'+ carril].value;
        det.average_speed = Math.round(this['average_speed_'+ carril].value);
        det.average_length = Math.round(this['average_length_'+ carril].value);
        det.gap = Math.round(this['gap_lenght_'+ carril].value);
        det.headway = Math.round(this['headway_lenght_'+ carril].value);
        det.fail_data = this['fail_data_'+ carril].value;
        det.veh_speed_1 = this['veh_speed_1_'+ carril].value;
        det.veh_speed_2 = this['veh_speed_2_'+ carril].value;
        det.veh_speed_3 = this['veh_speed_3_'+ carril].value;

        det.veh_pa_1 = this['volume0_'+ carril].value;
        det.veh_pa_2 = this['volume1_'+ carril].value;
        det.veh_pa_3 = this['volume2_'+ carril].value;
        det.veh_pa_4 = this['volume3_'+ carril].value;
        det.veh_pa_5 = this['volume4_'+ carril].value;
        det.veh_pa_6 = this['volume5_'+ carril].value;
        det.veh_pa_7 = this['volume6_'+ carril].value;
        det.veh_pa_8 = this['volume7_'+ carril].value;
        det.veh_pa_9 = this['volume8_'+ carril].value;
        det.veh_pa_10 = this['volume9_'+ carril].value;
        det.veh_pa_11 = this['volume10_'+ carril].value;
        det.veh_pa_12 = this['volume11_'+ carril].value;
        det.veh_pa_13 = this['volume12_'+ carril].value;

        etd.push(det);
    }
}

var jsonString = JSON.stringify(etd);

return jsonString;

sstGlobalScripts.script:
function datetotimestamp(dateString)
{


    var dateTimeParts = dateString.split(' '),
    timeParts = dateTimeParts[1].split(':'),
    dateParts = dateTimeParts[0].split('-');

    var date = new Date(parseInt(dateParts[0]), parseInt(dateParts[1]) - 1, parseInt(dateParts[2]), timeParts[0], timeParts[1]);

    var timestamp = date.getTime();

    return timestamp;
}
